42	    typename TileRight::TileDType __in__ bMatrix, uint16_t m, uint16_t k, uint16_t n, bool kDirectionAlign)
43	{
44	    __cc__ typename TileRes::DType* c = (__cc__ typename TileRes::DType*)__cce_get_tile_ptr(cMatrix);
45	    __ca__ typename TileLeft::DType* a = (__ca__ typename TileLeft::DType*)__cce_get_tile_ptr(aMatrix);
46	    __cb__ typename TileRight::DType* b = (__cb__ typename TileRight::DType*)__cce_get_tile_ptr(bMatrix);
47	    if constexpr (!isGemv) {
48	        if (m == 1) {
49	            m = 16; // avoid gemv mode, if m is 1, the gemv mode will be used in a3
50	        }
51	    }
52	    mad(c, a, b, m, k, n, static_cast<uint8_t>(Phase), kDirectionAlign, cmatrixSource, cmatrixInitVal);
53	}
