64	    __ca__ typename TileLeft::DType* a = (__ca__ typename TileLeft::DType*)__cce_get_tile_ptr(aMatrix);
65	    __cb__ typename TileRight::DType* b = (__cb__ typename TileRight::DType*)__cce_get_tile_ptr(bMatrix);
66	    __biasbuf__ typename TileBias::DType* d = (__biasbuf__ typename TileBias::DType*)__cce_get_tile_ptr(bias);
67	    uint64_t xd = ((uint64_t)c) & 0xffffffffULL | ((((uint64_t)d) & 0xffffffffULL) << 32);
68	    c = (__cc__ typename TileRes::DType*)xd;
69	    if constexpr (!isGemv) {
70	        if (m == 1) {
71	            m = 16; // avoid gemv mode, if m is 1, the gemv mode will be used in a3
72	        }
73	    }
74	    mad(c, a, b, m, k, n, static_cast<uint8_t>(Phase), kDirectionAlign, cmatrixSource, cmatrixInitVal);
