77	template <typename TileRes, typename TileLeft, typename TileRight>
78	PTO_INTERNAL void CheckStaticMad()
79	{
80	    using AType = typename TileLeft::DType;
81	    using BType = typename TileRight::DType;
82	    using CType = typename TileRes::DType;
83	    static_assert(
84	        ((std::is_same<CType, int32_t>::value) && (std::is_same<AType, int8_t>::value) &&
85	         (std::is_same<BType, int8_t>::value)) ||
86	            ((std::is_same<CType, float>::value) && (std::is_same<AType, half>::value) &&
87	             (std::is_same<BType, half>::value)) ||
88	            ((std::is_same<CType, float>::value) && (std::is_same<AType, float>::value) &&
89	             (std::is_same<BType, float>::value)) ||
90	            ((std::is_same<CType, float>::value) && (std::is_same<AType, bfloat16_t>::value) &&
91	             (std::is_same<BType, bfloat16_t>::value)),
92	        "The data type is not supported.");
93	
94	    static_assert(TileLeft::Loc == TileType::Left, "TileLeft TileType must be set to TileType::Left.");
95	    static_assert(TileRight::Loc == TileType::Right, "TileRight TileType must be set to TileType::Right.");
96	    static_assert(TileRes::Loc == TileType::Acc, "TileRes TileType must be set to TileType::Acc.");
97	}
