20	
21	template <typename TileAcc, typename TileLeft, typename TileRight>
22	PTO_INTERNAL void CheckMadValid()
23	{
24	    using AType = typename TileLeft::DType;
25	    using BType = typename TileRight::DType;
26	    using CType = typename TileAcc::DType;
27	    static_assert(
28	        (std::is_same_v<AType, int8_t> && std::is_same_v<BType, int8_t> && std::is_same_v<CType, int32_t>) || // s8
29	            (std::is_same_v<AType, half> && std::is_same_v<BType, half> && std::is_same_v<CType, float>) ||   // f162f32
30	            (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, bfloat16_t> &&
31	             std::is_same_v<CType, float>) ||                                                              // bf162f32
32	            (std::is_same_v<AType, float> && std::is_same_v<BType, float> && std::is_same_v<CType, float>) // f322f32
33	        ,
34	        "Not supported data type");
35	    static_assert(
36	        (TileLeft::Rows == TileAcc::Rows) && (TileLeft::Cols == TileRight::Rows) && (TileRight::Cols == TileAcc::Cols),
37	        "Inconsistent number of m, k, n");
38	    // CPU simulation can see two equivalent Left-tile encodings:
39	    // - TileLeft<...> aliases use ColMajor B-layout in CPU builds
40	    // - PTOAS-generated kernels materialize explicit Tile<Left,...,RowMajor,...>
41	    //   declarations that still produce correct offsets through GetTileElementOffset.
42	    static_assert(
43	        ((TileLeft::Loc == TileType::Left) && (TileLeft::SFractal == SLayout::RowMajor)) &&
44	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
45	             (TileRight::SFractal == SLayout::ColMajor)) &&
46	            ((TileAcc::Loc == TileType::Acc) && (!TileAcc::isRowMajor) && (TileAcc::SFractal == SLayout::RowMajor)),
47	        "Non-conforming matrix fractal");
48	}
49	
50	template <typename TileAcc, typename TileLeft, typename TileRight>
51	void TMatmulNzZn(TileAcc& dst, TileAcc* acc, TileLeft& src0, TileRight& src1)
52	{
53	    CheckMadValid<TileAcc, TileLeft, TileRight>();
54	
55	    uint16_t M = src0.GetValidRow();
56	    uint16_t K = src0.GetValidCol();
57	    uint16_t N = src1.GetValidCol();
58	
59	    cpu::parallel_for_1d(0, M, static_cast<std::size_t>(M) * N * K, [&](std::size_t i) {
60	        for (uint16_t j = 0; j < N; j++) {
61	            typename TileAcc::DType mul_acc = 0;
62	
63	            PTO_CPU_VECTORIZE_LOOP
64	            for (uint16_t k = 0; k < K; k++) {
65	                auto a = static_cast<typename TileAcc::DType>(src0.GetElement(i, k));
66	                auto b = static_cast<typename TileAcc::DType>(src1.GetElement(k, j));
67	                if constexpr (std::is_same<float, typename TileAcc::DType>::value) {
68	                    mul_acc = std::fma(a, b, mul_acc);
69	                } else {
70	                    mul_acc += a * b;
71	                }
72	            }
73	
74	            dst.SetElement(i, j, acc ? acc->GetElement(i, j) + mul_acc : mul_acc);
75	        }
76	    });
77	}
78	
79	template <typename A, typename B>
80	constexpr bool isSupportedFp8Combo = (std::is_same_v<A, float8_e4m3_t> && std::is_same_v<B, float8_e4m3_t>) ||
81	                                     (std::is_same_v<A, float8_e4m3_t> && std::is_same_v<B, float8_e5m2_t>) ||
82	                                     (std::is_same_v<A, float8_e5m2_t> && std::is_same_v<B, float8_e4m3_t>) ||
83	                                     (std::is_same_v<A, float8_e5m2_t> && std::is_same_v<B, float8_e5m2_t>);
84	
85	template <typename A, typename B>
86	constexpr bool isSupportedFp4Combo = (std::is_same_v<A, float4_e1m2x2_t> && std::is_same_v<B, float4_e1m2x2_t>) ||
87	                                     (std::is_same_v<A, float4_e1m2x2_t> && std::is_same_v<B, float4_e2m1x2_t>) ||
88	                                     (std::is_same_v<A, float4_e2m1x2_t> && std::is_same_v<B, float4_e2m1x2_t>) ||
89	                                     (std::is_same_v<A, float4_e2m1x2_t> && std::is_same_v<B, float4_e1m2x2_t>);
